"""File-shaped models for Mantle authoring YAML.

Runtime specs flatten or rename some keys (``AgentSpec`` lifts
``orchestrator.preconditions`` and ``conversation.before_end``). These models
match the files authors write, and the JSON Schema generator exports them.
"""

from __future__ import annotations

from typing import Annotated, Any, Literal, Union

from pydantic import (
    BaseModel,
    ConfigDict,
    Field,
    RootModel,
    field_validator,
)

from rasa.core.config.available_endpoints import RecordingConfig
from rasa.mantle.config.a2a_server import MantleA2AServerConfig
from rasa.mantle.config.agent_spec import (
    AgentPromptConfig,
    AgentVoiceConfig,
    FillersConfig,
    KnowledgeAnsweringConfig,
    SkillRetrievalConfig,
    VoiceSettingsConfig,
)
from rasa.mantle.config.builtin_tool_constraints import BuiltinToolConstraints
from rasa.mantle.config.channels import ChannelConfig
from rasa.mantle.config.integrations import KnowledgeStoreConfig, MCPServerSpec
from rasa.mantle.config.preconditions import PreconditionBinding
from rasa.mantle.config.runtime_endpoints import (
    EventBrokerSettings,
    LockStoreSettings,
    ModelServerSettings,
    SecretsManagerSettings,
    TimerStoreSettings,
    TrackerStoreSettings,
)
from rasa.mantle.config.session_spec import SessionSpec
from rasa.mantle.config.tracing import (
    JaegerTracingSettings,
    LangfuseTracingSettings,
    OtlpCollectorSettings,
)
from rasa.mantle.memory.field import MemoryField
from rasa.mantle.memory.schema import SkillMemorySchema
from rasa.mantle.skills.frontmatter import RequiresConfirmationDocument

_FORBID = ConfigDict(extra="forbid", frozen=True)

_TracingEntry = Union[
    LangfuseTracingSettings, OtlpCollectorSettings, JaegerTracingSettings
]


class AgentIdentityDocument(BaseModel):
    """The ``agent:`` block: identity, language, persona, and optional voice."""

    model_config = _FORBID

    id: str = ""
    language: str = ""
    persona: str
    voice: AgentVoiceConfig | None = None

    @field_validator("persona")
    @classmethod
    def _persona_non_empty(cls, value: str) -> str:
        """Reject a blank persona; it is the one required identity field."""
        if not isinstance(value, str) or not value.strip():
            raise ValueError("agent.persona must be a non-empty string")
        return value


class ConversationDocument(BaseModel):
    """The ``conversation:`` block."""

    model_config = _FORBID

    before_end: tuple[str, ...] = ()


class OrchestratorDocument(BaseModel):
    """The ``orchestrator:`` block as authored, including precondition bindings.

    ``model_group`` names the ``model_groups`` entry in ``integrations.yml``
    that drives the agent; ``max_prompt_tokens`` is an optional prompt budget.
    ``tool_constraints`` may set a confirmation gate on ``cancel`` only.
    """

    model_config = _FORBID

    model_group: str = Field(min_length=1)
    text_rules: str = ""
    voice_rules: str = ""
    max_prompt_tokens: int | None = Field(default=None, gt=0)
    preconditions: dict[str, PreconditionBinding] = Field(default_factory=dict)
    tool_constraints: BuiltinToolConstraints = Field(default_factory=dict)


class VoiceSettingsDocument(VoiceSettingsConfig):
    """Top-level ``voice:`` block in ``agent.yml``.

    ``silence_timeout`` replaces ``interaction_handling.global_silence_timeout``
    from ``endpoints.yml``. A voice channel's own ``silence_timeout`` overrides it.
    """

    model_config = _FORBID


class AgentYmlDocument(BaseModel):
    """Authoring shape of ``agent.yml``.

    ``orchestrator`` is required: it names the model group that drives the
    agent, and that name has no default. Preconditions stay under
    ``orchestrator.preconditions``. There is no top-level ``preconditions`` key.
    """

    model_config = ConfigDict(extra="forbid", frozen=True, title="agent.yml")

    agent: AgentIdentityDocument
    rules: tuple[str, ...] = ()
    fillers: FillersConfig = Field(default_factory=FillersConfig)
    prompts: AgentPromptConfig = Field(default_factory=AgentPromptConfig)
    knowledge_answering: KnowledgeAnsweringConfig = Field(
        default_factory=KnowledgeAnsweringConfig
    )
    conversation: ConversationDocument = Field(default_factory=ConversationDocument)
    tool_timeout: float | None = Field(default=None, gt=0, allow_inf_nan=False)
    session_config: SessionSpec = Field(default_factory=SessionSpec)
    skill_retrieval: SkillRetrievalConfig = Field(default_factory=SkillRetrievalConfig)
    voice: VoiceSettingsDocument | None = None
    orchestrator: OrchestratorDocument


class IntegrationsYmlDocument(BaseModel):
    """Authoring shape of ``integrations.yml``.

    ``model_groups`` stays a list of mappings; the orchestrator names its group
    in ``agent.yml``, so there is no ``llm:`` key. Channel entries allow
    channel-specific keys. ``tracing`` is one tracer or a list of tracers.
    ``metrics`` is an OTLP collector. ``a2a_server`` is the top-level inbound
    A2A block, not a channel. ``event_broker``, ``timer_store``,
    ``tracker_store``, ``lock_store``, ``secrets_manager``,
    ``rasa_model_server``, and ``recordings`` use the same models startup
    validates.
    """

    model_config = ConfigDict(extra="forbid", frozen=True, title="integrations.yml")

    mcp_servers: list[MCPServerSpec] = Field(default_factory=list)
    knowledge_stores: list[KnowledgeStoreConfig] = Field(default_factory=list)
    model_groups: list[dict[str, Any]] = Field(default_factory=list)
    channels: dict[str, ChannelConfig | None] = Field(default_factory=dict)
    tracing: _TracingEntry | list[_TracingEntry] | None = None
    metrics: OtlpCollectorSettings | None = None
    a2a_server: MantleA2AServerConfig | None = None
    event_broker: EventBrokerSettings | None = None
    timer_store: TimerStoreSettings | None = None
    tracker_store: TrackerStoreSettings | None = None
    lock_store: LockStoreSettings | None = None
    secrets_manager: SecretsManagerSettings | None = None
    rasa_model_server: ModelServerSettings | None = None
    recordings: RecordingConfig | None = None


class ProjectMemoryYmlDocument(RootModel[dict[str, MemoryField]]):
    """Project ``memory.yml``: a flat map of field name to declaration."""

    model_config = ConfigDict(title="memory.yml")


class SkillMemoryYmlDocument(BaseModel):
    """Skill ``memory.yml``: a ``schema`` block with ``public`` and ``private``."""

    model_config = ConfigDict(
        extra="forbid",
        frozen=True,
        populate_by_name=True,
        title="skill memory.yml",
    )

    definition: SkillMemorySchema = Field(
        default_factory=SkillMemorySchema, alias="schema"
    )


class ResponseButtonDocument(BaseModel):
    """One static button on a response variant."""

    model_config = _FORBID

    title: str
    payload: str | None = None


class ResponseButtonSourceDocument(BaseModel):
    """A tool that supplies a variant's buttons at delivery time."""

    model_config = _FORBID

    source: str


class ResponseVariantDocument(BaseModel):
    """One response variant as written in ``responses.yml``."""

    model_config = _FORBID

    text: str = ""
    condition: str | None = None
    metadata: dict[str, Any] = Field(default_factory=dict)
    buttons: list[ResponseButtonDocument] | ResponseButtonSourceDocument | None = None


class ResponsesYmlDocument(BaseModel):
    """Authoring shape of ``responses.yml`` (the ``responses:`` wrapper)."""

    model_config = ConfigDict(extra="forbid", frozen=True, title="responses.yml")

    responses: dict[str, list[ResponseVariantDocument | str]] = Field(
        default_factory=dict
    )


class IfBranchDocument(BaseModel):
    """A conditional ``next`` branch (``if`` / ``then``)."""

    model_config = ConfigDict(extra="forbid", frozen=True, populate_by_name=True)

    if_: str = Field(alias="if")
    then: str


class ElseBranchDocument(BaseModel):
    """The fallback ``next`` branch (``else``)."""

    model_config = ConfigDict(extra="forbid", frozen=True, populate_by_name=True)

    else_: str = Field(alias="else")


NextBranchDocument = Annotated[
    Union[IfBranchDocument, ElseBranchDocument],
    Field(),
]
NextDocument = str | list[NextBranchDocument]


class AutonomousStepDocument(BaseModel):
    """An ordered-block step with ``instructions:``."""

    model_config = _FORBID

    id: str
    instructions: str
    complete_when: str | None = None
    optional: bool = False
    next: NextDocument | None = None


class CollectStepDocument(BaseModel):
    """An ordered-block step with ``collect:``."""

    model_config = _FORBID

    id: str
    collect: str
    utterance: str | None = None
    description: str | None = None
    ask_before_filling: bool = False
    next: NextDocument | None = None


class ActionStepDocument(BaseModel):
    """An ordered-block step with ``action:``."""

    model_config = _FORBID

    id: str
    action: str
    next: NextDocument | None = None


class UtterStepDocument(BaseModel):
    """An ordered-block step with the legacy ``utter:`` key."""

    model_config = _FORBID

    id: str
    utter: str
    next: NextDocument | None = None


class RouteStepDocument(BaseModel):
    """An ordered-block step with ``noop: true``."""

    model_config = _FORBID

    id: str
    noop: Literal[True]
    next: NextDocument | None = None


class ExecuteStepDocument(BaseModel):
    """An ordered-block step with ``execute_tool:``."""

    model_config = _FORBID

    id: str
    execute_tool: str
    parameters: dict[str, Any] = Field(default_factory=dict)
    next: NextDocument | None = None


class SetMemoryStepDocument(BaseModel):
    """An ordered-block step with ``set_memory:``."""

    model_config = _FORBID

    id: str
    set_memory: dict[str, Any]
    next: NextDocument | None = None


class CallStepDocument(BaseModel):
    """An ordered-block step with ``call:``."""

    model_config = _FORBID

    id: str
    call: str
    next: NextDocument | None = None


class LinkStepDocument(BaseModel):
    """An ordered-block step with ``link:``."""

    model_config = _FORBID

    id: str
    link: str


class EndStepDocument(BaseModel):
    """The ``id: END`` sentinel step."""

    model_config = _FORBID

    id: Literal["END"]


OrderedBlockStepDocument = Annotated[
    Union[
        CollectStepDocument,
        ExecuteStepDocument,
        SetMemoryStepDocument,
        AutonomousStepDocument,
        ActionStepDocument,
        UtterStepDocument,
        RouteStepDocument,
        CallStepDocument,
        LinkStepDocument,
        EndStepDocument,
    ],
    Field(),
]


class OrderedBlockToolDocument(BaseModel):
    """One ordered-block ``tools:`` entry that carries constraint options."""

    model_config = _FORBID

    name: str
    requires: str | None = None
    requires_confirmation: RequiresConfirmationDocument | None = None
    on_success: str | None = None
    on_failure: str | None = None


class OrderedBlockDocument(BaseModel):
    """Authoring shape of one ``:::ordered_block`` body.

    Steps use the YAML keys authors write (``collect``, ``execute_tool``),
    not the engine's internal ``kind``. ``routable`` is engine-owned and is
    not part of this contract.
    """

    model_config = ConfigDict(extra="forbid", frozen=True, title="ordered block")

    steps: list[OrderedBlockStepDocument] = Field(default_factory=list)
    tools: list[str | OrderedBlockToolDocument] = Field(default_factory=list)
    complete_when: str | None = None
